const M = {};
M.config = (function () {
  const module = { exports: {} };
/**
 * config.js – builds the runtime config for every workflow from environment variables.
 * Used by the first "Config" Code node in each workflow. Secrets are NOT copied into
 * the output (execution data is stored in n8n); HTTP nodes read tokens from $env directly.
 */
function bool(v, dflt) {
  if (v === undefined || v === null || v === '') return dflt;
  return String(v).trim().toLowerCase() === 'true';
}

function parseList(v) {
  return String(v || '')
    .split(/[,;\s]+/)
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
}

function parseLimit(v, demoMode) {
  if (v === undefined || v === null || v === '') return demoMode ? 10 : null;
  if (String(v).trim().toLowerCase() === 'off') return null;
  const n = parseInt(v, 10);
  return Number.isFinite(n) && n > 0 ? n : 10;
}

function trimSlash(u) {
  return String(u || '').replace(/\/+$/, '');
}

function buildConfig(env) {
  env = env || {};
  // Safe defaults: demo mode ON unless explicitly "false".
  const demoMode = bool(env.DEMO_MODE, true);
  const mock = bool(env.MOCK_EXTERNAL, false);
  const mockBase = trimSlash(env.MOCK_BASE_URL || 'http://host.docker.internal:8787');
  const real = {
    airtable: 'https://api.airtable.com/v0',
    googlePlaces: 'https://places.googleapis.com/v1',
    openai: 'https://api.openai.com/v1',
    anthropic: 'https://api.anthropic.com/v1',
    slack: 'https://slack.com/api',
    gmail: 'https://gmail.googleapis.com/gmail/v1',
    hubspot: 'https://api.hubapi.com',
    dns: 'https://dns.google',
    web: '',
    calendly: 'https://api.calendly.com',
  };
  const mocked = {
    airtable: mockBase + '/airtable/v0',
    googlePlaces: mockBase + '/google/v1',
    openai: mockBase + '/ai/openai/v1',
    anthropic: mockBase + '/ai/anthropic/v1',
    slack: mockBase + '/slack/api',
    gmail: mockBase + '/gmail/v1',
    hubspot: mockBase + '/hubspot',
    dns: mockBase + '/dns',
    web: mockBase + '/web',
    calendly: mockBase + '/calendly',
  };
  const urls = mock ? mocked : real;
  const aiProvider = String(env.AI_PROVIDER || 'openai').toLowerCase() === 'anthropic' ? 'anthropic' : 'openai';
  const allowlist = parseList(env.TEST_RECIPIENT_ALLOWLIST);
  const conf = parseFloat(env.AUTO_REPLY_MIN_CONFIDENCE);
  return {
    demoMode,
    mock,
    allowRealSending: !demoMode && bool(env.ALLOW_REAL_SENDING, false),
    // DEMO_MODE sends from an every-minute ticker; the test stack turns it off and drives sends by webhook
    demoTicker: !bool(env.DISABLE_DEMO_TICKER, false),
    // cap per run so one run always finishes before the next tick (no overlapping runs)
    maxSendsPerRun: demoMode ? 6 : 5,
    testLeadLimit: parseLimit(env.TEST_LEAD_LIMIT, demoMode),
    allowlist,
    testProspectEmail: String(env.TEST_PROSPECT_EMAIL || '').trim().toLowerCase(),
    senderEmail: String(env.SENDER_EMAIL || '').trim().toLowerCase(),
    autoReplyMinConfidence: Number.isFinite(conf) ? conf : 0.85,
    unsureConfidence: 0.7,
    timezone: 'Europe/Berlin',
    airtableBaseId: env.AIRTABLE_BASE_ID || '',
    airtableUrl: urls.airtable + '/' + (env.AIRTABLE_BASE_ID || ''),
    googlePlacesUrl: urls.googlePlaces,
    aiProvider,
    aiModel: env.AI_MODEL || (aiProvider === 'anthropic' ? 'claude-haiku-5-5' : 'gpt-4o-mini'),
    aiUrl: aiProvider === 'anthropic' ? urls.anthropic + '/messages' : urls.openai + '/chat/completions',
    slackApiUrl: urls.slack,
    slackChannel: env.SLACK_CHANNEL || '#leads',
    gmailUrl: urls.gmail,
    hubspotUrl: urls.hubspot,
    dnsUrl: urls.dns,
    webProxyUrl: urls.web,
    calendlyLink: env.CALENDLY_LINK || '',
    calendlyApiUrl: urls.calendly,
    n8nBaseUrl: trimSlash(env.WEBHOOK_URL || 'http://localhost:5678'),
    n8nInternalUrl: trimSlash(env.N8N_INTERNAL_URL || 'http://localhost:5678'),
    interfaceUrl: env.AIRTABLE_INTERFACE_URL || (env.AIRTABLE_BASE_ID ? 'https://airtable.com/' + env.AIRTABLE_BASE_ID : ''),
    googleCostPerRequestEur: 0.032,
  };
}

/** URL to fetch a company web page; in mock mode served by the mock server. */
function webUrl(cfg, domain, path) {
  path = path || '/';
  if (cfg.webProxyUrl) return cfg.webProxyUrl + '/' + domain + path;
  return 'https://' + domain + path;
}

const configApi = { buildConfig, webUrl, parseList, parseLimit };
if (typeof module !== 'undefined' && module.exports) module.exports = configApi;

  return module.exports;
})();

// ---- node logic ----
const trigger = $input.all().map((i) => i.json);
// test stack only: schedules are switched off so tests drive every module through its webhook
const scheduled = trigger.length > 0 && trigger[0] && trigger[0]['Readable date'] !== undefined;
if (scheduled && String($env.DISABLE_SCHEDULES).toLowerCase() === 'true') return [];
return [{ json: { cfg: M.config.buildConfig($env), trigger, startedAt: new Date().toISOString() } }];

const M = {};
M.airtable = (function () {
  const module = { exports: {} };
/**
 * airtable.js – helpers for the Airtable REST API: batches of 10, formula building,
 * flattening records. Free-plan friendly (CLAUDE.md: batches of 10 per call).
 */
const BATCH = 10;

function chunk(list, size) {
  const n = size || BATCH;
  const out = [];
  for (let i = 0; i < (list || []).length; i += n) out.push(list.slice(i, i + n));
  return out;
}

function clean(fields) {
  const out = {};
  Object.keys(fields || {}).forEach((k) => {
    if (fields[k] !== undefined) out[k] = fields[k];
  });
  return out;
}

/** -> [{records:[{fields}]}] one item per HTTP call */
function createBatches(fieldsList) {
  return chunk((fieldsList || []).map((f) => ({ fields: clean(f) }))).map((records) => ({ records, typecast: true }));
}

/** updates: [{id, fields}] -> [{records:[{id, fields}]}] */
function updateBatches(updates) {
  return chunk((updates || []).filter((u) => u && u.id).map((u) => ({ id: u.id, fields: clean(u.fields) }))).map((records) => ({ records, typecast: true }));
}

function esc(v) {
  return String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
}

function eq(field, value) {
  if (typeof value === 'number' || typeof value === 'boolean') return `{${field}}=${value === true ? 'TRUE()' : value === false ? 'FALSE()' : value}`;
  return `{${field}}='${esc(value)}'`;
}

function and(...parts) {
  const p = parts.filter(Boolean);
  return p.length === 1 ? p[0] : `AND(${p.join(',')})`;
}

function or(...parts) {
  const p = parts.filter(Boolean);
  return p.length === 1 ? p[0] : `OR(${p.join(',')})`;
}

/** Airtable record -> flat object with id */
function flat(record) {
  if (!record) return null;
  return Object.assign({ id: record.id, createdTime: record.createdTime }, record.fields || {});
}

function flatList(response) {
  return ((response && response.records) || []).map(flat);
}

/** n8n items from a (paginated) list node -> flat records */
function fromItems(items) {
  // With pagination on, n8n's HTTP node retries and then passes the error body on instead of failing.
  // A failed read must never look like an empty table (e.g. an "empty" Blocklist), so fail here.
  (items || []).forEach((i) => {
    const e = i && i.json && i.json.error;
    if (e) throw new Error('Airtable read failed after retries: ' + (typeof e === 'string' ? e : e.message || e.type || JSON.stringify(e)).slice(0, 200));
  });
  return flatList({ records: (items || []).flatMap((i) => (i && i.json && i.json.records) || []) });
}

/** OR() over ids for a text field, e.g. lead_record_id */
function inIds(field, ids) {
  const list = Array.from(new Set((ids || []).filter(Boolean)));
  if (!list.length) return "{" + field + "}='__none__'";
  return or(...list.map((id) => eq(field, id)));
}

const airtableApi = { fromItems, inIds, BATCH, chunk, createBatches, updateBatches, eq, and, or, esc, flat, flatList, clean };
if (typeof module !== 'undefined' && module.exports) module.exports = airtableApi;

  return module.exports;
})();

M.report = (function () {
  const module = { exports: {} };
/**
 * report.js – Module 8 metrics: funnel, rates, costs and the per-client guarantee tracker.
 */
function linkOf(v) {
  return Array.isArray(v) ? v[0] : v;
}

const CONTACTED_OR_LATER = ['Contacted', 'Replied', 'Interested', 'Later', 'Not interested', 'Unsubscribed', 'Bounced', 'Meeting booked', 'Meeting held', 'No-show'];
const POSITIVE = ['Interested', 'Meeting booked', 'Meeting held', 'No-show'];
const MEETING = ['Meeting booked', 'Meeting held', 'No-show'];

function within(dateStr, from, to) {
  if (!dateStr) return false;
  const t = new Date(dateStr).getTime();
  return (!from || t >= new Date(from).getTime()) && (!to || t < new Date(to).getTime());
}

function round(n, d) {
  const f = Math.pow(10, d === undefined ? 2 : d);
  return Math.round(n * f) / f;
}

/** data: {campaigns, leads, emails, replies, meetings}; period: {from, to} (optional) */
function campaignMetrics(campaign, data, period) {
  period = period || {};
  const leads = (data.leads || []).filter((l) => linkOf(l.campaign) === campaign.id || l.campaign_record_id === campaign.id);
  const leadIds = new Set(leads.map((l) => l.id));
  const inPeriod = (d) => !period.from || within(d, period.from, period.to);
  const emails = (data.emails || []).filter((e) => leadIds.has(linkOf(e.lead)) && e.status === 'Sent' && inPeriod(e.sent_at));
  const replies = (data.replies || []).filter((r) => leadIds.has(linkOf(r.lead)) && inPeriod(r.received_at));
  const meetings = (data.meetings || []).filter((m) => leadIds.has(linkOf(m.lead)) && m.status !== 'Cancelled' && inPeriod(m.start_time || m.created_at));
  const sourced = leads.filter((l) => inPeriod(l.sourced_at)).length;
  const enriched = leads.filter((l) => l.status !== 'New' && l.status !== 'Rejected' && inPeriod(l.sourced_at)).length;
  const contactedLeads = new Set(emails.map((e) => linkOf(e.lead))).size;
  const repliedLeads = new Set(replies.filter((r) => r.category !== 'Bounce').map((r) => linkOf(r.lead))).size;
  // positive = wants to talk or asks a concrete question before agreeing (both are real interest, not auto-replies)
  const positive = replies.filter((r) => r.category === 'Interested' || r.category === 'Question').length;
  const held = meetings.filter((m) => m.status === 'Held').length;
  const cost = (Number(campaign.google_api_cost_eur) || 0) + (Number(campaign.ai_cost_eur) || 0);
  return {
    campaign_id: campaign.id,
    name: campaign.name,
    client: linkOf(campaign.client) || null,
    leads_sourced: sourced,
    enriched,
    enriched_pct: sourced ? round((enriched / sourced) * 100, 1) : 0,
    emails_sent: emails.length,
    contacted: contactedLeads,
    replied: repliedLeads,
    reply_rate_pct: contactedLeads ? round((repliedLeads / contactedLeads) * 100, 1) : 0,
    positive_replies: positive,
    meetings_booked: meetings.length,
    meetings_held: held,
    cost_eur: round(cost, 4),
    cost_per_lead_eur: sourced ? round(cost / sourced, 4) : 0,
    cost_per_meeting_eur: meetings.length ? round(cost / meetings.length, 4) : null,
    funnel: { sourced, enriched, contacted: contactedLeads, replied: repliedLeads, interested: positive, meeting_booked: meetings.length },
  };
}

function monthStart(now) {
  const d = new Date(now);
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), 1)).toISOString();
}

/** Positive replies and meetings this month vs. the client's targets. */
function guaranteeTracker(client, data, now) {
  const from = monthStart(now || Date.now());
  const camps = (data.campaigns || []).filter((c) => linkOf(c.client) === client.id);
  let positive = 0;
  let meetings = 0;
  camps.forEach((c) => {
    const m = campaignMetrics(c, data, { from });
    positive += m.positive_replies;
    meetings += m.meetings_booked;
  });
  const tp = Number(client.target_positive_replies) || 20;
  const tm = Number(client.target_meetings) || 4;
  return {
    client_id: client.id,
    name: client.name,
    positive_replies: positive,
    target_positive_replies: tp,
    positive_pct: round(Math.min(100, (positive / tp) * 100), 1),
    meetings,
    target_meetings: tm,
    meetings_pct: round(Math.min(100, (meetings / tm) * 100), 1),
  };
}

function progressBar(pct) {
  const filled = Math.round(Math.max(0, Math.min(100, pct)) / 10);
  return '█'.repeat(filled) + '░'.repeat(10 - filled) + ` ${pct}%`;
}

function weeklyFacts(data, now) {
  const to = new Date(now || Date.now());
  const from = new Date(to.getTime() - 7 * 86400000);
  return (data.campaigns || [])
    .filter((c) => ['Live', 'Paused', 'Completed', 'Ready'].includes(c.status))
    .map((c) => campaignMetrics(c, data, { from: from.toISOString(), to: to.toISOString() }));
}

const reportApi = { campaignMetrics, guaranteeTracker, progressBar, weeklyFacts, monthStart, POSITIVE, MEETING, CONTACTED_OR_LATER };
if (typeof module !== 'undefined' && module.exports) module.exports = reportApi;

  return module.exports;
})();

M.dashboard = (function () {
  const module = { exports: {} };
/**
 * dashboard.js – the live dashboard (GET /webhook/dashboard[?client=<id>]), computed from Airtable on every load.
 * Per client: the guarantee (positive replies vs 20, meetings vs 4–5 this month, on track or behind for the day of the
 * month), the funnel, cost per lead and meeting, every campaign, the A/B subject test, recent replies, upcoming meetings.
 * Pure function: data in, escaped HTML out, so it is unit-tested without n8n. Uses report.js for the numbers.
 */
// in n8n the builder embeds report.js first as M.report; in Node (tests) it is required
function rep() {
  /* global M */
  if (typeof M !== 'undefined' && M.report) return M.report;
  return require('./report'); // eslint-disable-line global-require
}

function esc(s) {
  return String(s === undefined || s === null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}
const link = (v) => (Array.isArray(v) ? v[0] : v);
// small amounts (cost per lead is ~0.001 €) keep their significant digits instead of rounding to 0,00 €
const eur = (n) => {
  if (n === null || n === undefined || !Number.isFinite(Number(n))) return '–';
  const v = Number(n);
  const digits = v !== 0 && Math.abs(v) < 0.1 ? 4 : 2;
  return v.toLocaleString('de-DE', { minimumFractionDigits: digits, maximumFractionDigits: digits }) + ' €';
};
const pct = (a, b) => (b ? Math.round((a / b) * 1000) / 10 : 0);

/** Share of the month already elapsed (Berlin time is close enough to UTC for a monthly pace). */
function monthElapsed(now) {
  const d = new Date(now);
  const days = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate();
  return Math.min(1, (d.getUTCDate() - 1 + d.getUTCHours() / 24) / days);
}

/** On track when the target share reached is at least the share of the month elapsed (5 % grace). */
function pace(value, target, now) {
  const need = monthElapsed(now) * target;
  if (value >= target) return { state: 'good', label: 'Ziel erreicht', icon: '✓' };
  if (value + 0.05 * target >= need) return { state: 'good', label: 'im Plan', icon: '✓' };
  return { state: 'warning', label: 'hinter Plan (Soll heute ' + Math.ceil(need) + ')', icon: '!' };
}

/** A/B test of the first subject line: sent and replied leads per variant, winner once both have 20+ sends. */
function abTest(campaign, data) {
  const leads = (data.leads || []).filter((l) => l.campaign_record_id === campaign.id || link(l.campaign) === campaign.id);
  const byId = Object.fromEntries(leads.map((l) => [l.id, l]));
  const sent = (data.emails || []).filter((e) => byId[e.lead_record_id || link(e.lead)] && Number(e.step) === 1 && e.status === 'Sent');
  const replied = new Set((data.replies || []).filter((r) => r.category && r.category !== 'Bounce' && r.category !== 'Out of office').map((r) => r.lead_record_id || link(r.lead)));
  const v = { A: { sent: 0, replied: 0 }, B: { sent: 0, replied: 0 } };
  sent.forEach((e) => {
    const l = byId[e.lead_record_id || link(e.lead)];
    const k = l.subject_variant === 'B' ? 'B' : 'A';
    v[k].sent += 1;
    if (replied.has(l.id)) v[k].replied += 1;
  });
  ['A', 'B'].forEach((k) => { v[k].rate = pct(v[k].replied, v[k].sent); });
  const first = sent.find((e) => e.subject) || {};
  const b = sent.find((e) => e.subject_b) || {};
  const winner = v.A.sent >= 20 && v.B.sent >= 20 && v.A.rate !== v.B.rate ? (v.A.rate > v.B.rate ? 'A' : 'B') : null;
  return { subject_a: first.subject || '', subject_b: b.subject_b || '', A: v.A, B: v.B, winner };
}

function dashboardData(input) {
  const o = input || {};
  const now = o.now || Date.now();
  const data = { campaigns: o.campaigns || [], leads: o.leads || [], emails: o.emails || [], replies: o.replies || [], meetings: o.meetings || [] };
  const clients = (o.clients || []).filter((c) => !o.clientId || c.id === o.clientId);
  const ids = new Set(clients.map((c) => c.id));
  const campaigns = data.campaigns.filter((c) => ids.has(link(c.client) || c.client_record_id))
    .sort((a, b) => String(b.created_at || '').localeCompare(String(a.created_at || '')));
  const rows = campaigns.map((c) => Object.assign(rep().campaignMetrics(c, data), { status: c.status, clientName: (clients.find((k) => k.id === (link(c.client) || c.client_record_id)) || {}).name, ab: abTest(c, data) }));
  const sum = (k) => rows.reduce((a, r) => a + (Number(r[k]) || 0), 0);
  const totals = { leads_sourced: sum('leads_sourced'), enriched: sum('enriched'), emails_sent: sum('emails_sent'), contacted: sum('contacted'), replied: sum('replied'),
    positive_replies: sum('positive_replies'), meetings_booked: sum('meetings_booked'), cost_eur: sum('cost_eur') };
  totals.reply_rate_pct = pct(totals.replied, totals.contacted);
  totals.cost_per_lead_eur = totals.leads_sourced ? totals.cost_eur / totals.leads_sourced : null;
  totals.cost_per_meeting_eur = totals.meetings_booked ? totals.cost_eur / totals.meetings_booked : null;
  const guarantees = clients.map((k) => {
    const g = rep().guaranteeTracker(k, Object.assign({}, data, { campaigns: data.campaigns.map((c) => Object.assign({}, c, { client: link(c.client) || c.client_record_id })) }), now);
    return Object.assign(g, { replyPace: pace(g.positive_replies, g.target_positive_replies, now), meetingPace: pace(g.meetings, g.target_meetings, now) });
  });
  const leadById = Object.fromEntries(data.leads.map((l) => [l.id, l]));
  const campIds = new Set(campaigns.map((c) => c.id));
  const inScope = (leadId) => { const l = leadById[leadId]; return l && campIds.has(l.campaign_record_id || link(l.campaign)); };
  const recent = data.replies.filter((r) => inScope(r.lead_record_id || link(r.lead))).sort((a, b) => String(b.received_at).localeCompare(String(a.received_at))).slice(0, 8)
    .map((r) => ({ when: r.received_at, company: (leadById[r.lead_record_id || link(r.lead)] || {}).company_name, category: r.category, summary: r.summary }));
  const upcoming = data.meetings.filter((m) => m.status !== 'Cancelled' && inScope(m.lead_record_id || link(m.lead)) && new Date(m.start_time).getTime() >= new Date(now).getTime() - 3600000)
    .sort((a, b) => String(a.start_time).localeCompare(String(b.start_time))).slice(0, 6)
    .map((m) => ({ when: m.start_time, company: (leadById[m.lead_record_id || link(m.lead)] || {}).company_name, contact: (leadById[m.lead_record_id || link(m.lead)] || {}).contact_name, status: m.status }));
  return { now, clients: o.clients || [], selected: o.clientId || '', rows, totals, guarantees, recent, upcoming };
}

const berlin = (iso) => (iso ? new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }).format(new Date(iso)) : '');

function bar(value, max, label, title) {
  const w = max ? Math.max(value ? 2 : 0, Math.round((value / max) * 100)) : 0;
  return `<div class="bar" title="${esc(title || label)}"><span class="fill" style="width:${w}%"></span></div>`;
}

function renderDashboard(input) {
  const d = dashboardData(input);
  const t = d.totals;
  const tiles = [
    ['Positive Antworten', t.positive_replies, 'Interessiert oder konkrete Frage'],
    ['Termine gebucht', t.meetings_booked, 'über den Calendly-Link'],
    ['Antwortquote', t.reply_rate_pct + ' %', t.replied + ' von ' + t.contacted + ' kontaktierten Firmen'],
    ['E-Mails gesendet', t.emails_sent, 'inkl. Follow-ups'],
    ['Kosten pro Lead', eur(t.cost_per_lead_eur), 'Google + KI'],
    ['Kosten pro Termin', eur(t.cost_per_meeting_eur), 'Google + KI, ohne Personal'],
  ].map(([k, v, s]) => `<div class="tile"><div class="k">${esc(k)}</div><div class="v">${esc(v)}</div><div class="s">${esc(s)}</div></div>`).join('');
  const guarantee = d.guarantees.map((g) => `<div class="card"><h3>${esc(g.name)} · Garantie diesen Monat</h3>
    ${[['Positive Antworten', g.positive_replies, g.target_positive_replies, g.replyPace], ['Qualifizierte Termine', g.meetings, g.target_meetings, g.meetingPace]].map(([k, v, tg, p]) => `
    <div class="g"><div class="gl"><span>${esc(k)}</span><b>${esc(v)} / ${esc(tg)}</b></div>${bar(Math.min(v, tg), tg, k, k + ': ' + v + ' von ' + tg)}
    <div class="st ${p.state}"><span aria-hidden="true">${p.icon}</span> ${esc(p.label)}</div></div>`).join('')}</div>`).join('');
  const f = [['Gefunden (Google)', t.leads_sourced], ['Angereichert', t.enriched], ['Kontaktiert', t.contacted], ['Geantwortet', t.replied], ['Positiv', t.positive_replies], ['Termin', t.meetings_booked]];
  const funnel = f.map(([k, v], i) => `<div class="fr"><span class="fk">${esc(k)}</span>${bar(v, f[0][1], k, k + ': ' + v + (i ? ' (' + pct(v, f[i - 1][1]) + ' % der vorherigen Stufe)' : ''))}<span class="fv">${esc(v)}${i ? ' <small>' + pct(v, f[i - 1][1]) + ' %</small>' : ''}</span></div>`).join('');
